/**
 * SkillCorner Body Pose Viewer.
 *
 * File map:
 * 1. prepares state, colors, the 3D scene, and the camera;
 * 2. draws the pitch, lines, and goals;
 * 3. creates player markers and extracts poses and gaze direction;
 * 4. positions the camera and redraws each clip frame;
 * 5. builds the shot library and loads the selected clip;
 * 6. controls playback, resizing, and the render loop;
 * 7. starts the introduction and viewer.
 *
 * Data comes from html/data/manifest.json and html/data/clips/, generated by
 * notebook 00. The stadium is built by html/stadium.js.
 */
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { buildStadium } from "./stadium.js?v=20261111-4";

// 1. State, colors, scene, and camera
